/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3 -c 'import importlib, pylint; print(\"pylint\", pylint.__version__); 
for m in [\"pylint.checkers.similar\",\"pylint.checkers.symilar\"]:
    try:
        mod=importlib.import_module(m); print(\"MODULE\",m,\"file\",getattr(mod,\"__file__\",None));
        [print(\" \", name, getattr(mod,name)) for name in [\"LineSet\",\"Similar\",\"SimilaritiesChecker\",\"hash_lineset\",\"stripped_lines\",\"remove_successive\",\"similarities\",\"Run\"] if hasattr(mod,name)]
    except Exception as e:
        print(\"ERR\",m,repr(e))'"

