/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3 -c 'from pylint.checkers.symilar import Symilar, LineSet; 
for n in [7,8,9]:
    lines=[f\"x{i}= {i}\\n\" for i in range(n)]; s=Symilar(min_lines=8, ignore_comments=True, ignore_docstrings=True, ignore_imports=True, ignore_signatures=True); a=LineSet(\"a.py\", lines, True, True, True, True); b=LineSet(\"b.py\", lines, True, True, True, True); print(n, list(s._find_common(a,b)))'"

